// Renders the AI-generated (or template) explanation for a path.
// Shows a loading skeleton while the mutation is pending, labels template
// explanations honestly ("Deterministic summary"), and always adds a
// "Generated by AI from the data shown" note for LLM outputs (plan 4.6).
// Needs a PathExplanationOut or null, plus a loading flag.
import type { PathExplanationOut } from '../../../types/api';

interface Props {
  explanation: PathExplanationOut | null;
  isLoading: boolean;
}

function Skeleton() {
  return (
    <div role="status" aria-label="Generating explanation" className="space-y-2 animate-pulse">
      <div className="h-4 w-3/4 rounded bg-slate-800" />
      <div className="h-3 w-full rounded bg-slate-800" />
      <div className="h-3 w-5/6 rounded bg-slate-800" />
    </div>
  );
}

export function ExplanationBlock({ explanation, isLoading }: Props) {
  if (isLoading) {
    return <Skeleton />;
  }

  if (!explanation) {
    return (
      <p className="text-xs text-slate-500 italic">
        Explanation not yet generated — click "Generate Explanations" above.
      </p>
    );
  }

  const isTemplate = explanation.generated_by === 'template';

  return (
    <div className="space-y-2 text-sm">
      {/* Source label */}
      <p className="text-[10px] uppercase tracking-wide text-slate-500">
        {isTemplate ? 'Template fallback (deterministic)' : 'AI-generated from the data shown'}
      </p>

      <p className="font-semibold text-white">{explanation.headline}</p>

      {explanation.reasons.length > 0 && (
        <ul className="list-disc list-inside space-y-0.5 text-slate-300" aria-label="Reasons">
          {explanation.reasons.map((r, i) => (
            <li key={i}>{r}</li>
          ))}
        </ul>
      )}

      {explanation.caveat && (
        <p className="text-slate-400">
          <span className="text-slate-500">Note: </span>
          {explanation.caveat}
        </p>
      )}

      {explanation.next_step && (
        <p className="text-slate-300">
          <span className="text-slate-500">Next step: </span>
          {explanation.next_step}
        </p>
      )}
    </div>
  );
}
